SELECT DISTINCT
  bte.operator_id,
  bte.service_id,
  bte.service_provider_name,
  src.location_name AS source_city,
  dst.location_name AS destination_city,
  bte.state
FROM transaction.bus_ticket_events AS bte
LEFT JOIN lis.config_locations AS src
  ON bte.src_location_id = src.id AND src.location_type = 'CITY' AND src.is_expired = 0
LEFT JOIN lis.config_locations AS dst
  ON bte.destination_location_id = dst.id
  AND dst.location_type = 'CITY'
  AND dst.is_expired = 0
WHERE
  bte.country_code = 'IND'
  AND bte.event_type = 101
  AND bte.time_of_event >= CAST('2026-07-11 00:00:00' AS TIMESTAMP)
  AND bte.time_of_event < CAST('2026-08-10 00:00:00' AS TIMESTAMP)
  AND bte.operator_id IN (10061, 15155, 15625, 15850, 16882, 16892, 16896, 16982, 17042, 17086, 17113, 17199, 17397, 17479, 17571, 17607, 18012, 18294, 18539, 19368, 19748, 20132, 20174, 20205, 20310, 20575, 20660, 20820, 21312, 21334, 21466, 21479, 21569, 21793, 22221, 22301, 22391, 22414, 22876, 22908, 22956, 23223, 23224, 23243, 23295, 23552, 23947, 23997, 24254, 24470, 2472, 25023, 25034, 25087, 25210, 25471, 25472, 25748, 25761, 25945, 27230, 27518, 27534, 27619, 27699, 27824, 27838, 27874, 27906, 28033, 28071, 29261, 29288, 29294, 29357, 29421, 29440, 29452, 29742, 29927, 30234, 30318, 30469, 30785, 30994, 31041, 31249, 31333, 31457, 31779, 31790, 31837, 31866, 31872, 32009, 32037, 32072, 32146, 32257, 32405, 32437, 33079, 33149, 33168, 33190, 33243, 33410, 33625, 34117, 34182, 34365, 34374, 34505, 34519, 34587, 34660, 34704, 34807, 34842, 34932, 34978, 34985, 35167, 35184, 35225, 35387, 35408, 35512, 35515, 35518, 35522, 35549, 35603, 35607, 35754, 35806, 35808, 35811, 35949, 36001, 36005, 36031, 36047, 36062, 36094, 36112, 36270, 36311, 36376, 36424, 36463, 36486, 36523, 36562, 36584, 36604, 36618, 36642, 36699, 36760, 36779, 36780, 36824, 36857, 36867, 36871, 36877, 36937, 37019, 37035, 37053, 37074, 37094, 37140, 37178, 37193, 37197, 37254, 37315, 37398, 37413, 37508, 37722, 37789, 37883, 4708, 5369, 6414, 6494, 8332)
ORDER BY
  bte.operator_id,
  bte.service_id,
  source_city,
  destination_city
LIMIT 20000